import Foundation

/// Learned "which word did you mean?" model: a score for each candidate word (higher = more likely),
/// from 9 facts about it. Generated by `tools/train learn-rank`. Don't edit by hand; retrain instead.
/// Facts, in order: slip cost, word frequency, fits left word, fits right word, length change, same first letter, same last letter, stopped one key short, contraction.
enum RankModel {
    static var forceOff = false   // training/testing: use the hand-written formula instead
    static var isTrained: Bool { !weights.isEmpty && !forceOff }

    static let mean: [Double] = [1.477180, 6.602676, 0.268116, 0.228831, 1.081544, 0.399319, 0.444915, 0.004556, 0.002607]
    static let scale: [Double] = [0.463102, 1.224505, 0.853684, 0.794259, 0.786623, 0.489759, 0.496956, 0.067343, 0.050995]
    static let weights: [Double] = [-3.320433, 1.530843, 0.715839, 0.574603, -0.498298, 0.611510, 0.575221, 0.080541, 0.022344]

    static func score(_ x: [Double]) -> Double {
        var z = 0.0
        for i in 0..<weights.count { z += weights[i] * (x[i] - mean[i]) / scale[i] }
        return z
    }
}
